// Accepts form submissions and IoT payloads (object, array or {records:[]})
const num = v => (v === '' || v === null || v === undefined) ? null : (Number(v) || 0);
const toISO = v => {
  const s = String(v || '').trim();
  const m = s.match(/^(\d{2})[-/](\d{2})[-/](\d{4})$/);            // DD-MM-YYYY
  return m ? `${m[3]}-${m[2]}-${m[1]}` : s.slice(0, 10);
};
const raw = $input.all().flatMap(({ json: j }) => {
  if (j['Machine ID'] !== undefined) return [{ source: 'form', r: {
    date: j['Date'], shift: j['Shift'], machine_id: j['Machine ID'], line: j['Line'],
    planned_time_min: j['Planned Production Time (min)'], downtime_min: j['Downtime (min)'],
    downtime_reasons: j['Downtime Reasons'], ideal_cycle_time_sec: j['Ideal Cycle Time (sec)'],
    total_count: j['Total Count'], good_count: j['Good Count'], startup_rejects: j['Startup Rejects'],
    operator: j['Operator Name'] } }];
  const body = j.body ?? j;
  const arr = Array.isArray(body) ? body : Array.isArray(body.records) ? body.records : [body];
  return arr.map(r => ({ source: 'iot', r: { ...r, operator: r.operator || r.device_id || 'iot-gateway' } }));
});

const out = [];
for (const { source, r } of raw) {
  const flags = [];
  const machine = String(r.machine_id || '').trim().toUpperCase();
  const shift = String(r.shift || '').trim().toUpperCase().charAt(0);
  const date = toISO(r.date);
  if (!machine || !['A', 'B', 'C'].includes(shift) || !/^\d{4}-\d{2}-\d{2}$/.test(date)) continue; // reject malformed
  const planned = num(r.planned_time_min) ?? 0;
  let downtime = num(r.downtime_min) ?? 0, total = num(r.total_count) ?? 0, good = num(r.good_count) ?? 0;
  let startup = num(r.startup_rejects) ?? 0;
  if (planned <= 0) flags.push('planned time missing');
  if (downtime > planned) { flags.push('downtime>planned (capped)'); downtime = planned; }
  if (good > total) { flags.push('good>total (capped)'); good = total; }
  if (startup > total - good) { flags.push('startup rejects>scrap (capped)'); startup = total - good; }
  const reasons = String(r.downtime_reasons || '').trim();
  const reasonSum = reasons ? reasons.split(';').map(s => Number(s.split(':')[1]) || 0).reduce((a, b) => a + b, 0) : 0;
  if (reasons && Math.abs(reasonSum - downtime) > 5) flags.push(`reason min ${reasonSum} vs downtime ${downtime}`);
  out.push({ json: {
    entry_key: `${date}_${shift}_${machine}_${source}`, date, shift, machine_id: machine, line: r.line || '',
    planned_time_min: planned, downtime_min: downtime, downtime_reasons: reasons,
    ideal_cycle_time_sec: num(r.ideal_cycle_time_sec) ?? '', total_count: total, good_count: good,
    startup_rejects: startup, operator: r.operator || '', source, logged_at: new Date().toISOString(),
    data_flags: flags.join('; ')
  } });
}
return out;

// Shift A 06-14, B 14-22, C 22-06 (C belongs to the date it started)
const now = $now.setZone('Asia/Kolkata');
const h = now.hour;
let shift, date;
if (h >= 6 && h < 14) { shift = 'C'; date = now.minus({ days: 1 }); }
else if (h >= 14 && h < 22) { shift = 'A'; date = now; }
else { shift = 'B'; date = h < 6 ? now.minus({ days: 1 }) : now; }
return [{ json: {
  shift, shift_date: date.toFormat('yyyy-LL-dd'), shift_label: `Shift ${shift} | ${date.toFormat('dd LLL yyyy')}`,
  plant_name: 'Plant 1',
  oee_target: 0.65,            // world-class 0.85
  critical_threshold: 0.50,    // below this a work order is raised
  breakdown_alert_min: 60,     // equipment-failure minutes that force escalation
  z_threshold: -2,             // anomaly vs 7-day shift baseline
  baseline_days: 7,
  plant_head_whatsapp: 'REPLACE_WITH_PLANT_HEAD_NUMBER',
  maintenance_whatsapp: 'REPLACE_WITH_MAINTENANCE_NUMBER'
}}];

const cfg = $('Identify Completed Shift').first().json;
const master = $('Read Machine Master').all().map(i => i.json)
  .filter(m => m.machine_id && String(m.active ?? 'yes').toLowerCase() !== 'no');
const MM = Object.fromEntries(master.map(m => [String(m.machine_id).toUpperCase(), m]));
const rows = $input.all().map(i => i.json).filter(r => r.machine_id && r.date);
const num = v => Number(v) || 0;
const r1 = x => Math.round(x * 1000) / 10;
const SHIFT_ORDER = { A: 1, B: 2, C: 3 };

// ---- loss taxonomy (TPM Six Big Losses) ----
const LOSS_MAP = [
  [/break|fail|electric|mechan|hydraul|pneumat|motor|bearing|spindle|tool ?broke|leak/i, 'Equipment Failure'],
  [/change ?over|setup|set-up|adjust|die|mou?ld|calib|warm ?up|trial/i, 'Setup & Adjustments'],
  [/minor|small|jam|idle|block|starv|sensor|material|feed|operator|clean/i, 'Idling & Minor Stops'],
];
const classify = r => (LOSS_MAP.find(([re]) => re.test(r)) || [null, 'Other Stops'])[1];
const parseReasons = s => String(s || '').split(';').map(x => x.trim()).filter(Boolean)
  .map(x => { const [r, m] = x.split(':'); const reason = (r || 'Unspecified').trim(); return { reason, min: num(m), loss: classify(reason) }; });

// ---- merge form + IoT entries for the same machine & shift ----
const consolidate = list => {
  const g = {};
  for (const r of list) {
    const k = `${String(r.date).slice(0, 10)}|${String(r.shift).toUpperCase()}|${String(r.machine_id).toUpperCase()}`;
    (g[k] = g[k] || []).push(r);
  }
  return Object.values(g).map(grp => {
    const iot = grp.find(r => r.source === 'iot'), form = grp.find(r => r.source === 'form');
    const base = { ...(iot || form || grp[0]) };
    if (iot && form) {
      if (!iot.downtime_reasons) base.downtime_reasons = form.downtime_reasons;
      base.operator = form.operator;
      base.data_flags = [base.data_flags, 'merged form+iot (iot counts used)'].filter(Boolean).join('; ');
    }
    base.machine_id = String(base.machine_id).toUpperCase();
    base.shift = String(base.shift).toUpperCase();
    base.date = String(base.date).slice(0, 10);
    const ideal = num(base.ideal_cycle_time_sec) || num(MM[base.machine_id]?.ideal_cycle_time_sec);
    if (!ideal) base.data_flags = [base.data_flags, 'no ideal cycle time'].filter(Boolean).join('; ');
    base.ideal = ideal;
    base.line = base.line || MM[base.machine_id]?.line || '';
    return base;
  });
};

const calc = list => {
  let planned = 0, down = 0, idealMin = 0, total = 0, good = 0, startupMin = 0, prodRejMin = 0, failures = 0;
  const losses = { 'Equipment Failure': 0, 'Setup & Adjustments': 0, 'Idling & Minor Stops': 0, 'Other Stops': 0 };
  for (const r of list) {
    const p = num(r.planned_time_min), d = Math.min(num(r.downtime_min), p), t = num(r.total_count);
    const g = Math.min(num(r.good_count), t), su = Math.min(num(r.startup_rejects), t - g);
    planned += p; down += d; total += t; good += g;
    idealMin += r.ideal * t / 60;
    startupMin += r.ideal * su / 60; prodRejMin += r.ideal * (t - g - su) / 60;
    const rs = parseReasons(r.downtime_reasons);
    rs.forEach(x => { losses[x.loss] += x.min; if (x.loss === 'Equipment Failure') failures++; });
    const logged = rs.reduce((a, x) => a + x.min, 0);
    if (d > logged) losses['Other Stops'] += d - logged;          // unexplained downtime
  }
  const run = Math.max(planned - down, 0);
  const A = planned ? run / planned : 0, P = run ? Math.min(idealMin / run, 1) : 0, Q = total ? good / total : 0;
  const goodIdealMin = idealMin - startupMin - prodRejMin;
  const speedLoss = Math.max(run - idealMin, 0);
  return { planned, downtime: down, run, total, good, A, P, Q, OEE: A * P * Q,
    six_big_losses: { ...losses, 'Reduced Speed': Math.round(speedLoss), 'Startup Rejects': Math.round(startupMin), 'Production Rejects': Math.round(prodRejMin) },
    fully_productive_min: Math.round(goodIdealMin), failures,
    mttr_min: failures ? Math.round(losses['Equipment Failure'] / failures) : null,
    mtbf_min: failures ? Math.round(run / failures) : null };
};

const all = consolidate(rows);
const isCur = r => r.date === cfg.shift_date && r.shift === cfg.shift;
const cur = all.filter(isCur);
const reportedIds = new Set(cur.map(r => r.machine_id));
const missing = master.map(m => String(m.machine_id).toUpperCase()).filter(id => !reportedIds.has(id));
if (!cur.length) return [{ json: { ...cfg, has_data: false, missing_machines: missing } }];

const since = new Date(cfg.shift_date); since.setDate(since.getDate() - cfg.baseline_days);
const hist = all.filter(r => !isCur(r) && new Date(r.date) >= since && new Date(r.date) <= new Date(cfg.shift_date));

const machines = [...reportedIds].map(id => {
  const k = calc(cur.filter(r => r.machine_id === id));
  // per-shift history series for z-score & trend
  const hm = hist.filter(r => r.machine_id === id)
    .sort((a, b) => a.date.localeCompare(b.date) || SHIFT_ORDER[a.shift] - SHIFT_ORDER[b.shift]);
  const series = hm.map(r => calc([r]).OEE);
  const mean = series.length ? series.reduce((a, b) => a + b, 0) / series.length : null;
  const sd = series.length > 1 ? Math.sqrt(series.reduce((a, b) => a + (b - mean) ** 2, 0) / (series.length - 1)) : 0;
  const z = series.length >= 3 ? Math.round((k.OEE - mean) / Math.max(sd, 0.03) * 100) / 100 : null; // 3-pt OEE floor avoids divide-by-near-zero
  const last3 = [...series.slice(-2), k.OEE];
  const declining = last3.length === 3 && last3[0] > last3[1] && last3[1] > last3[2];
  const recurring = {};
  hm.forEach(r => parseReasons(r.downtime_reasons).forEach(x => recurring[x.reason] = (recurring[x.reason] || 0) + 1));
  const reasons = {};
  cur.filter(r => r.machine_id === id).forEach(r => parseReasons(r.downtime_reasons).forEach(x => reasons[x.reason] = (reasons[x.reason] || 0) + x.min));
  const triggers = [];
  if (k.OEE < cfg.critical_threshold) triggers.push(`OEE below ${cfg.critical_threshold * 100}%`);
  if (z !== null && z <= cfg.z_threshold) triggers.push(`anomaly z=${z}`);
  if (k.six_big_losses['Equipment Failure'] >= cfg.breakdown_alert_min) triggers.push(`${k.six_big_losses['Equipment Failure']} min breakdown`);
  const topLoss = Object.entries(k.six_big_losses).sort((a, b) => b[1] - a[1])[0];
  return { machine_id: id, line: cur.find(r => r.machine_id === id).line,
    oee: r1(k.OEE), availability: r1(k.A), performance: r1(k.P), quality: r1(k.Q),
    downtime_min: k.downtime, total: k.total, good: k.good, scrap: k.total - k.good,
    six_big_losses: k.six_big_losses, top_loss: topLoss[1] > 0 ? `${topLoss[0]} (${topLoss[1]} min)` : 'none',
    mttr_min: k.mttr_min, mtbf_min: k.mtbf_min, failures: k.failures,
    baseline_7d_oee: mean === null ? null : r1(mean), delta_vs_7d: mean === null ? null : r1(k.OEE - mean),
    z_score: z, declining_trend: declining, reasons,
    recurring_reasons_7d: Object.entries(recurring).filter(([, n]) => n >= 2).map(([r, n]) => `${r} (${n} shifts)`),
    critical: triggers.length > 0, critical_triggers: triggers,
    data_flags: cur.filter(r => r.machine_id === id && r.data_flags).map(r => r.data_flags).join('; ') };
}).sort((a, b) => a.oee - b.oee);

const plant = calc(cur);
const pareto = {};
cur.forEach(r => parseReasons(r.downtime_reasons).forEach(x => pareto[x.reason] = (pareto[x.reason] || 0) + x.min));
const paretoList = Object.entries(pareto).sort((a, b) => b[1] - a[1])
  .map(([reason, min]) => ({ reason, min, loss: classify(reason), pct: plant.downtime ? Math.round(min / plant.downtime * 100) : 0 }));
const lossTotals = Object.entries(plant.six_big_losses).sort((a, b) => b[1] - a[1]).map(([loss, min]) => ({ loss, min }));

return [{ json: { ...cfg, has_data: true,
  plant: { oee: r1(plant.OEE), availability: r1(plant.A), performance: r1(plant.P), quality: r1(plant.Q),
    downtime_min: plant.downtime, total: plant.total, good: plant.good, machines_reported: machines.length,
    mttr_min: plant.mttr_min, mtbf_min: plant.mtbf_min, fully_productive_min: plant.fully_productive_min, planned_min: plant.planned },
  six_big_losses: lossTotals, machines, pareto: paretoList, missing_machines: missing,
  critical_machines: machines.filter(m => m.critical).map(m => m.machine_id) } }];

