=Analyse this shift and return the structured root-cause report.

SHIFT DATA:
{{ JSON.stringify({ shift: $json.shift_label, target_oee_pct: $json.oee_target * 100, plant: $json.plant, six_big_losses: $json.six_big_losses, pareto: $json.pareto.slice(0, 8), critical_machines: $json.critical_machines, missing_machines: $json.missing_machines, machines: $json.machines.map(m => ({ id: m.machine_id, oee: m.oee, A: m.availability, P: m.performance, Q: m.quality, top_loss: m.top_loss, mttr: m.mttr_min, mtbf: m.mtbf_min, z: m.z_score, declining: m.declining_trend, delta_vs_7d: m.delta_vs_7d, recurring: m.recurring_reasons_7d, triggers: m.critical_triggers })) }) }}

