const d = $('Calculate OEE & Six Big Losses').first().json;
const ai = $input.first().json.output || {};
const tgt = d.oee_target * 100;
const dot = v => v >= tgt ? '🟢' : v >= d.critical_threshold * 100 ? '🟡' : '🔴';
const aiFor = id => (ai.patterns || []).find(p => String(p.machine_id).toUpperCase() === id) || {};

const lines = [
  `🏭 *${d.plant_name} – OEE Shift Report*`, d.shift_label, '',
  `${dot(d.plant.oee)} *Plant OEE ${d.plant.oee}%* (target ${tgt}%)`,
  `A ${d.plant.availability}% · P ${d.plant.performance}% · Q ${d.plant.quality}%`,
  `Good ${d.plant.good}/${d.plant.total} · Downtime ${d.plant.downtime_min} min` +
    (d.plant.mttr_min ? ` · MTTR ${d.plant.mttr_min}m · MTBF ${d.plant.mtbf_min}m` : ''), '',
  '*Six Big Losses (min)*',
  ...d.six_big_losses.filter(l => l.min > 0).slice(0, 4).map(l => `▪️ ${l.loss}: ${l.min}`), '',
  '*Machines*',
  ...d.machines.map(m => `${dot(m.oee)} ${m.machine_id}: ${m.oee}%` +
    (m.delta_vs_7d !== null ? ` (${m.delta_vs_7d >= 0 ? '▲' : '▼'}${Math.abs(m.delta_vs_7d)} vs 7d)` : '') +
    (m.z_score !== null && m.z_score <= d.z_threshold ? ' ⚡anomaly' : '') + (m.declining_trend ? ' 📉3-shift decline' : '')),
  ...(d.missing_machines.length ? ['', `⛔ No data: ${d.missing_machines.join(', ')}`] : []),
  '', `🧠 *Root cause:* ${ai.headline || '-'}`,
  ...(ai.patterns || []).map(p => `• [${p.priority}] ${p.machine_id}: ${p.probable_root_cause}${p.repeat_after_repair ? ' 🔁 repeat after repair' : ''}\n   ➜ ${p.recommended_action}`),
  ...((ai.quick_wins || []).length ? ['', '*Quick wins next shift*', ...ai.quick_wins.map(q => `✅ ${q}`)] : []),
  ...(d.critical_machines.length ? ['', `🛠️ Work orders raised or updated for: ${d.critical_machines.join(', ')}`] : [])
];

// QuickChart: Pareto (bars + cumulative %) or, if no reasons were logged, OEE by machine vs target
let chart;
if (d.pareto.length) {
  const top = d.pareto.slice(0, 8); let c = 0; const tot = top.reduce((a, p) => a + p.min, 0);
  chart = { type: 'bar', data: { labels: top.map(p => p.reason), datasets: [
    { type: 'line', label: 'Cumulative %', data: top.map(p => Math.round((c += p.min) / tot * 100)), borderColor: '#17344d', fill: false, yAxisID: 'pct' },
    { label: 'Downtime (min)', data: top.map(p => p.min), backgroundColor: '#e4572e', yAxisID: 'min' } ] },
    options: { title: { display: true, text: `Downtime Pareto – ${d.shift_label}` },
      scales: { yAxes: [{ id: 'min', ticks: { beginAtZero: true } }, { id: 'pct', position: 'right', ticks: { min: 0, max: 100 } }] } } };
} else {
  chart = { type: 'bar', data: { labels: d.machines.map(m => m.machine_id), datasets: [
    { label: 'OEE %', data: d.machines.map(m => m.oee), backgroundColor: d.machines.map(m => m.oee >= tgt ? '#2e9e5b' : '#e4572e') },
    { type: 'line', label: 'Target', data: d.machines.map(() => tgt), borderColor: '#17344d', fill: false } ] },
    options: { title: { display: true, text: `OEE by machine – ${d.shift_label}` }, scales: { yAxes: [{ ticks: { min: 0, max: 100 } }] } } };
}
const chart_url = 'https://quickchart.io/chart?w=900&h=500&bkg=white&c=' + encodeURIComponent(JSON.stringify(chart));

const critical_items = d.machines.filter(m => m.critical).map(m => ({
  machine_id: m.machine_id, line: m.line, shift: d.shift, shift_date: d.shift_date, shift_label: d.shift_label,
  oee: m.oee, downtime_min: m.downtime_min, mttr_min: m.mttr_min, top_loss: m.top_loss,
  triggers: m.critical_triggers.join('; '),
  ai_root_cause: aiFor(m.machine_id).probable_root_cause || m.top_loss,
  recommended_action: aiFor(m.machine_id).recommended_action || 'Inspect machine; log detailed downtime reasons',
  ai_priority: aiFor(m.machine_id).priority || 'High',
  repeat_after_repair: !!aiFor(m.machine_id).repeat_after_repair }));

const history_rows = d.machines.map(m => ({ date: d.shift_date, shift: d.shift, machine_id: m.machine_id, line: m.line,
  oee_pct: m.oee, availability_pct: m.availability, performance_pct: m.performance, quality_pct: m.quality,
  downtime_min: m.downtime_min, total: m.total, good: m.good, top_loss: m.top_loss,
  equipment_failure_min: m.six_big_losses['Equipment Failure'], setup_min: m.six_big_losses['Setup & Adjustments'],
  minor_stops_min: m.six_big_losses['Idling & Minor Stops'], reduced_speed_min: m.six_big_losses['Reduced Speed'],
  startup_rejects_min: m.six_big_losses['Startup Rejects'], production_rejects_min: m.six_big_losses['Production Rejects'],
  mttr_min: m.mttr_min ?? '', mtbf_min: m.mtbf_min ?? '', z_score: m.z_score ?? '', baseline_7d_oee: m.baseline_7d_oee ?? '',
  critical: m.critical ? 'Yes' : 'No', ai_headline: ai.headline || '', data_flags: m.data_flags,
  reported_at: new Date().toISOString() }));

return [{ json: { report: lines.join('\n').slice(0, 4000), chart_url, critical_items, history_rows,
  plant_head_whatsapp: d.plant_head_whatsapp, maintenance_whatsapp: d.maintenance_whatsapp,
  caption: `${d.shift_label} · Plant OEE ${d.plant.oee}%` } }];

const items = $input.all().map(i => i.json).filter(t => t.ticket_id);
if (!items.length) return [];
const c = $('Compose Report & Pareto Chart').first().json;
const label = items[0].last_seen_shift || '';
const order = { Critical: 0, High: 1, Medium: 2, Low: 3 };
const lines = [`🚨 *Maintenance Escalation – ${label}*`, `${items.length} machine(s) need attention`, '',
  ...items.sort((a, b) => (order[a.priority] ?? 9) - (order[b.priority] ?? 9)).map(t =>
    `*${t.machine_id}* · ${t.ticket_id}\n` +
    `${Number(t.occurrences) > 1 ? `🔁 REPEAT x${t.occurrences}` : '🆕 NEW'} · ${t.priority} · OEE ${t.last_oee_pct}%\n` +
    `Cause: ${t.ai_root_cause || '-'}\n➜ ${t.recommended_action}`)];
return [{ json: { to: c.maintenance_whatsapp, text: lines.join('\n\n').slice(0, 4000) } }];

const m = $('Loop Over Critical Machines').first().json;
const now = new Date().toISOString();
const open = $input.all().map(i => i.json)
  .filter(r => String(r.machine_id || '').toUpperCase() === m.machine_id && r.ticket_id && !/closed|done|resolved|cancel/i.test(r.status || ''));
const t = open.sort((a, b) => String(b.updated_at).localeCompare(String(a.updated_at)))[0];
const occurrences = t ? (Number(t.occurrences) || 1) + 1 : 1;
// priority escalation: AI priority, bumped to Critical on 3+ repeats or repeat-after-repair
const priority = occurrences >= 3 || m.repeat_after_repair ? 'Critical' : (m.ai_priority || 'High');
return [{ json: { ...m, exists: !!t, occurrences, priority,
  ticket_id: t ? t.ticket_id : `WO-${m.machine_id}-${m.shift_date.replace(/-/g, '')}-${m.shift}`,
  opened_at: t ? t.opened_at : now, updated_at: now } }];
